export const meta = {
  name: 'count-files',
  description: 'Count files by extension in a folder, three readers in parallel',
  phases: [{ title: 'Read' }, { title: 'Merge' }],
}

const COUNT = { type: 'object', required: ['ext', 'count'], properties: { ext: { type: 'string' }, count: { type: 'integer' } } }
const EXTS = ['.ts', '.js', '.json']

phase('Read')
const counts = await parallel(EXTS.map((ext) => () =>
  agent(`Count the files ending in ${ext} under ${args.folder}. Use Glob. Return ext and count.`,
    { schema: COUNT, model: 'haiku', effort: 'low', phase: 'Read' })))

phase('Merge')
const total = counts.filter(Boolean).reduce((sum, c) => sum + c.count, 0)
log(`${total} files counted`)
return { counts: counts.filter(Boolean), total }

import { query, type HookCallback } from "@anthropic-ai/claude-agent-sdk";
const logWorkflowRun: HookCallback = async (input) => {
  if (input.hook_event_name === "PostToolUse") console.log("Workflow tool returned:", JSON.stringify(input.tool_response));
  return {};
};

for await (const msg of query({
  prompt: "Run the saved workflow count-files with args { folder: 'src' } and report its result.",
  options: {
    model: "claude-opus-5-5",
    effort: "medium",
    cwd: process.cwd(), // .claude/workflows/count-files.js lives here
    settingSources: ["project"], // project settings, so saved workflows in .claude/ load
    allowedTools: ["Read", "Glob", "Grep", "Workflow"], // Workflow must be allowed under dontAsk
    permissionMode: "dontAsk",
    settings: { enableWorkflows: true, workflowSizeGuideline: "small" }, // size is advice, not a cap
    hooks: { PostToolUse: [{ matcher: "Workflow", hooks: [logWorkflowRun] }] },
    env: { ...process.env, CLAUDE_CODE_WORKFLOW_MAX_CONCURRENT_AGENTS: "3" }, // like a lite VM
  },
})) {
  if (msg.type === "result") {
    console.log("result", msg.subtype, "cost", msg.total_cost_usd);
    for (const [model, use] of Object.entries(msg.modelUsage)) console.log(model, use.inputTokens, "in", use.outputTokens, "out");
  }
}

export const meta = {
  name: 'nova-research',
  description: 'Parallel research before planning; for fuzzy tickets, 3 plans and a judge',
  phases: [{ title: 'Research' }, { title: 'Plans' }, { title: 'Judge' }],
}

const POINTERS = { type: 'object', required: ['pointers'], properties: { pointers: { type: 'array', items: {
  type: 'object', required: ['where', 'why'], properties: { where: { type: 'string' }, why: { type: 'string' } } } } } }
const QUESTIONS = [
  'Where is the code this ticket is about? Return file:line pointers, most relevant first.',
  'Find up to 5 merged fcp PRs that changed the same area (gh, read-only). Return the PR number and what it teaches.',
  'Which existing tests cover this area, and how are they run? Return file:line pointers.',
  'Search the brain with the kb skill for pages about this area; return path@sha and the key fact. If there is no kb skill, say "skipped".',
]

phase('Research')
const found = await parallel(QUESTIONS.map((q) => () =>
  agent(`${q}\n\nTicket:\n${args.ticket}`, { schema: POINTERS, model: 'haiku', effort: 'medium', phase: 'Research' })))
const notes = found.filter(Boolean).flatMap((r) => r.pointers)
if (!args.fuzzy) return { notes }
